INSERT INTO public.course_catalog (id, slug, title, short_description, long_description, level, category, order_index, track, track_order, is_core, is_published)
INSERT INTO public.course_lessons (id, course_id, chapter_number, title, description)
INSERT INTO public.course_units (id, lesson_id, order_index, kind, text, translation_pt, ipa, explanation_note, syntax_groups, annotations, example_en, example_pt)
VALUES
  ('unit-collocations-b2-01-01', 'lesson-collocations-b2-01', 1, 'sentence', 'I need to make a decision soon.', 'Preciso tomar uma decisão logo.', '/aɪ niːd tuː meɪk ə dɪˈsɪʒən suːn/', '"Make a decision": em português se "toma" uma decisão, em inglês se "faz".', '[]'::jsonb, '[{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"need","pos":"verb","ipa":"/niːd/","gloss":"precisar"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"make","pos":"verb","ipa":"/meɪk/","gloss":"fazer; conseguir ir (make it)"},{"surface":"a","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"decision","pos":"noun","ipa":"/dɪˈsɪʒən/","gloss":"decisão"},{"surface":"soon","pos":"adverb","ipa":"/suːn/","gloss":"logo"}]'::jsonb, NULL, NULL),
  ('unit-collocations-b2-01-02', 'lesson-collocations-b2-01', 2, 'sentence', 'She made a mistake on the form.', 'Ela cometeu um erro no formulário.', '/ʃiː meɪd ə mɪˈsteɪk ɑːn ðə fɔːrm/', '"Make a mistake", nunca "do a mistake".', '[]'::jsonb, '[{"surface":"She","pos":"pronoun","ipa":"/ʃiː/","gloss":"ela"},{"surface":"made","pos":"verb","ipa":"/meɪd/","gloss":"fez, feito"},{"surface":"a","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"mistake","pos":"noun","ipa":"/mɪˈsteɪk/","gloss":"erro"},{"surface":"on","pos":"preposition","ipa":"/ɑːn/","gloss":"em, sobre"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"form","pos":"noun","ipa":"/fɔːrm/","gloss":"formulário"}]'::jsonb, NULL, NULL),
  ('unit-collocations-b2-01-03', 'lesson-collocations-b2-01', 3, 'sentence', 'Can you do me a favor?', 'Você pode me fazer um favor?', '/kæn juː duː miː ə ˈfeɪvər/', '"Do a favor": favor, tarefa e trabalho pedem "do".', '[]'::jsonb, '[{"surface":"Can","pos":"auxiliary verb","ipa":"/kæn/","gloss":"poder"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"do","pos":"auxiliary verb","ipa":"/duː/","gloss":"fazer; auxiliar de pergunta"},{"surface":"me","pos":"pronoun","ipa":"/miː/","gloss":"me, mim"},{"surface":"a","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"favor","pos":"noun","ipa":"/ˈfeɪvər/","gloss":"favor"}]'::jsonb, NULL, NULL),
  ('unit-collocations-b2-01-04', 'lesson-collocations-b2-01', 4, 'sentence', 'We have to do the dishes before we leave.', 'Temos que lavar a louça antes de sair.', '/wiː hæv tuː duː ðə ˈdɪʃɪz bɪˈfɔːr wiː liːv/', '"Do the dishes" = lavar a louça; "do" para tarefas de casa.', '[]'::jsonb, '[{"surface":"We","pos":"pronoun","ipa":"/wiː/","gloss":"nós, a gente"},{"surface":"have","pos":"verb","ipa":"/hæv/","gloss":"ter"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"do","pos":"auxiliary verb","ipa":"/duː/","gloss":"fazer; auxiliar de pergunta"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"dishes","pos":"noun","ipa":"/ˈdɪʃɪz/","gloss":"louça, pratos"},{"surface":"before","pos":"adverb","ipa":"/bɪˈfɔːr/","gloss":"antes"},{"surface":"we","pos":"pronoun","ipa":"/wiː/","gloss":"nós, a gente"},{"surface":"leave","pos":"verb","ipa":"/liːv/","gloss":"deixar"}]'::jsonb, NULL, NULL),
  ('unit-collocations-b2-01-05', 'lesson-collocations-b2-01', 5, 'sentence', 'He makes a lot of noise at night.', 'Ele faz muito barulho à noite.', '/hiː meɪks ə lɑːt ʌv nɔɪz æt naɪt/', '"Make noise": o barulho é produzido, então "make".', '[]'::jsonb, '[{"surface":"He","pos":"pronoun","ipa":"/hiː/","gloss":"ele"},{"surface":"makes","pos":"verb","ipa":"/meɪks/","gloss":"faz"},{"surface":"a","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"lot","pos":"noun","ipa":"/lɑːt/","gloss":"muito (a lot)"},{"surface":"of","pos":"preposition","ipa":"/ʌv/","gloss":"de"},{"surface":"noise","pos":"noun","ipa":"/nɔɪz/","gloss":"barulho"},{"surface":"at","pos":"preposition","ipa":"/æt/","gloss":"em, às"},{"surface":"night","pos":"noun","ipa":"/naɪt/","gloss":"noite"}]'::jsonb, NULL, NULL),
  ('unit-collocations-b2-01-06', 'lesson-collocations-b2-01', 6, 'sentence', 'I will make an effort to arrive on time.', 'Vou me esforçar para chegar na hora.', '/aɪ wɪl meɪk ən ˈɛfərt tuː əˈraɪv ɑːn taɪm/', '"Make an effort" = se esforçar.', '[]'::jsonb, '[{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"will","pos":"modal verb","ipa":"/wɪl/","gloss":"marca de futuro"},{"surface":"make","pos":"verb","ipa":"/meɪk/","gloss":"fazer; conseguir ir (make it)"},{"surface":"an","pos":"determiner","ipa":"/ən/","gloss":"um, uma"},{"surface":"effort","pos":"noun","ipa":"/ˈɛfərt/","gloss":"esforço"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"arrive","pos":"verb","ipa":"/əˈraɪv/","gloss":"chegar"},{"surface":"on","pos":"preposition","ipa":"/ɑːn/","gloss":"em, sobre"},{"surface":"time","pos":"noun","ipa":"/taɪm/","gloss":"vez; hora"}]'::jsonb, NULL, NULL),
  ('unit-collocations-b2-01-07', 'lesson-collocations-b2-01', 7, 'sentence', 'They did a great job on the project.', 'Eles fizeram um ótimo trabalho no projeto.', '/ðeɪ dɪd ə ɡreɪt dʒɑːb ɑːn ðə ˈprɑːdʒɛkt/', '"Do a job" / "do homework": atividade ou tarefa.', '[]'::jsonb, '[{"surface":"They","pos":"pronoun","ipa":"/ðeɪ/","gloss":"eles, elas"},{"surface":"did","pos":"verb","ipa":"/dɪd/","gloss":"fez"},{"surface":"a","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"great","pos":"adjective","ipa":"/ɡreɪt/","gloss":"ótimo"},{"surface":"job","pos":"noun","ipa":"/dʒɑːb/","gloss":"trabalho"},{"surface":"on","pos":"preposition","ipa":"/ɑːn/","gloss":"em, sobre"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"project","pos":"noun","ipa":"/ˈprɑːdʒɛkt/","gloss":"projeto"}]'::jsonb, NULL, NULL),
  ('unit-collocations-b2-01-08', 'lesson-collocations-b2-01', 8, 'sentence', 'It does not make any difference to me.', 'Para mim tanto faz.', '/ɪt dʌz nɑːt meɪk ˈɛni ˈdɪfrəns tuː miː/', '"Make a difference" = fazer diferença.', '[]'::jsonb, '[{"surface":"It","pos":"pronoun","ipa":"/ɪt/","gloss":"isso, ele, ela"},{"surface":"does","pos":"auxiliary verb","ipa":"/dʌz/","gloss":"auxiliar de pergunta (3ª pessoa)"},{"surface":"not","pos":"particle","ipa":"/nɑːt/","gloss":"não"},{"surface":"make","pos":"verb","ipa":"/meɪk/","gloss":"fazer; conseguir ir (make it)"},{"surface":"any","pos":"determiner","ipa":"/ˈɛni/","gloss":"algum, alguma"},{"surface":"difference","pos":"noun","ipa":"/ˈdɪfrəns/","gloss":"diferença"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"me","pos":"pronoun","ipa":"/miː/","gloss":"me, mim"}]'::jsonb, NULL, NULL),
  ('unit-collocations-b2-01-09', 'lesson-collocations-b2-01', 9, 'sentence', 'Let me make you a cup of tea.', 'Deixa eu te fazer uma xícara de chá.', '/lɛt miː meɪk juː ə kʌp ʌv tiː/', '"Make" para preparar comida e bebida.', '[]'::jsonb, '[{"surface":"Let","pos":"verb","ipa":"/lɛt/","gloss":"deixar, permitir"},{"surface":"me","pos":"pronoun","ipa":"/miː/","gloss":"me, mim"},{"surface":"make","pos":"verb","ipa":"/meɪk/","gloss":"fazer; conseguir ir (make it)"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"a","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"cup","pos":"noun","ipa":"/kʌp/","gloss":"xícara"},{"surface":"of","pos":"preposition","ipa":"/ʌv/","gloss":"de"},{"surface":"tea","pos":"noun","ipa":"/tiː/","gloss":"chá"}]'::jsonb, NULL, NULL),
  ('unit-collocations-b2-01-10', 'lesson-collocations-b2-01', 10, 'sentence', 'She did her best, but it was not enough.', 'Ela fez o melhor que pôde, mas não foi suficiente.', '/ʃiː dɪd hɜːr bɛst bʌt ɪt wɑːz nɑːt ɪˈnʌf/', '"Do your best" = dar o melhor de si.', '[]'::jsonb, '[{"surface":"She","pos":"pronoun","ipa":"/ʃiː/","gloss":"ela"},{"surface":"did","pos":"verb","ipa":"/dɪd/","gloss":"fez"},{"surface":"her","pos":"determiner","ipa":"/hɜːr/","gloss":"dela; a, lhe"},{"surface":"best","pos":"adjective","ipa":"/bɛst/","gloss":"melhor"},{"surface":"but","pos":"conjunction","ipa":"/bʌt/","gloss":"mas"},{"surface":"it","pos":"pronoun","ipa":"/ɪt/","gloss":"isso, ele, ela"},{"surface":"was","pos":"verb","ipa":"/wɑːz/","gloss":"foi, estava"},{"surface":"not","pos":"particle","ipa":"/nɑːt/","gloss":"não"},{"surface":"enough","pos":"adverb","ipa":"/ɪˈnʌf/","gloss":"o bastante"}]'::jsonb, NULL, NULL)
INSERT INTO public.course_lessons (id, course_id, chapter_number, title, description)
INSERT INTO public.course_units (id, lesson_id, order_index, kind, text, translation_pt, ipa, explanation_note, syntax_groups, annotations, example_en, example_pt)
VALUES
  ('unit-collocations-b2-02-01', 'lesson-collocations-b2-02', 1, 'sentence', 'I usually take a shower in the morning.', 'Geralmente tomo banho de manhã.', '/aɪ ˈjuːʒuəli teɪk ə ˈʃaʊər ɪn ðə ˈmɔːrnɪŋ/', '"Take a shower": em inglês se "pega" um banho.', '[]'::jsonb, '[{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"usually","pos":"adverb","ipa":"/ˈjuːʒuəli/","gloss":"geralmente"},{"surface":"take","pos":"verb","ipa":"/teɪk/","gloss":"pegar, levar"},{"surface":"a","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"shower","pos":"noun","ipa":"/ˈʃaʊər/","gloss":"banho de chuveiro"},{"surface":"in","pos":"preposition","ipa":"/ɪn/","gloss":"em, dentro de"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"morning","pos":"noun","ipa":"/ˈmɔːrnɪŋ/","gloss":"manhã"}]'::jsonb, NULL, NULL),
  ('unit-collocations-b2-02-02', 'lesson-collocations-b2-02', 2, 'sentence', 'Let us take a break for ten minutes.', 'Vamos fazer uma pausa de dez minutos.', '/lɛt ʌs teɪk ə breɪk fɔːr tɛn ˈmɪnɪts/', '"Take a break" = fazer uma pausa.', '[]'::jsonb, '[{"surface":"Let","pos":"verb","ipa":"/lɛt/","gloss":"deixar, permitir"},{"surface":"us","pos":"pronoun","ipa":"/ʌs/","gloss":"nós, nos"},{"surface":"take","pos":"verb","ipa":"/teɪk/","gloss":"pegar, levar"},{"surface":"a","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"break","pos":"noun","ipa":"/breɪk/","gloss":"pausa, intervalo"},{"surface":"for","pos":"preposition","ipa":"/fɔːr/","gloss":"para, por"},{"surface":"ten","pos":"numeral","ipa":"/tɛn/","gloss":"dez"},{"surface":"minutes","pos":"noun","ipa":"/ˈmɪnɪts/","gloss":"minutos"}]'::jsonb, NULL, NULL),
  ('unit-collocations-b2-02-03', 'lesson-collocations-b2-02', 3, 'sentence', 'She took a photo of the sunset.', 'Ela tirou uma foto do pôr do sol.', '/ʃiː tʊk ə ˈfoʊtoʊ ʌv ðə ˈsʌnsɛt/', '"Take a photo", não "make a photo".', '[]'::jsonb, '[{"surface":"She","pos":"pronoun","ipa":"/ʃiː/","gloss":"ela"},{"surface":"took","pos":"verb","ipa":"/tʊk/","gloss":"pegou, levou"},{"surface":"a","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"photo","pos":"noun","ipa":"/ˈfoʊtoʊ/","gloss":"foto"},{"surface":"of","pos":"preposition","ipa":"/ʌv/","gloss":"de"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"sunset","pos":"noun","ipa":"/ˈsʌnsɛt/","gloss":"pôr do sol"}]'::jsonb, NULL, NULL),
  ('unit-collocations-b2-02-04', 'lesson-collocations-b2-02', 4, 'sentence', 'We had lunch at a small cafe.', 'Almoçamos numa cafeteria pequena.', '/wiː hæd lʌntʃ æt ə smɔːl kæˈfeɪ/', '"Have lunch" / "have breakfast": refeição pede "have".', '[]'::jsonb, '[{"surface":"We","pos":"pronoun","ipa":"/wiː/","gloss":"nós, a gente"},{"surface":"had","pos":"verb","ipa":"/hæd/","gloss":"teve, tinha"},{"surface":"lunch","pos":"noun","ipa":"/lʌntʃ/","gloss":"almoço"},{"surface":"at","pos":"preposition","ipa":"/æt/","gloss":"em, às"},{"surface":"a","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"small","pos":"adjective","ipa":"/smɔːl/","gloss":"pequeno"},{"surface":"cafe","pos":"noun","ipa":"/kæˈfeɪ/","gloss":"cafeteria"}]'::jsonb, NULL, NULL),
  ('unit-collocations-b2-02-05', 'lesson-collocations-b2-02', 5, 'sentence', 'I had a quick look at the report.', 'Dei uma olhada rápida no relatório.', '/aɪ hæd ə kwɪk lʊk æt ðə rɪˈpɔːrt/', '"Have a look" = dar uma olhada.', '[]'::jsonb, '[{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"had","pos":"verb","ipa":"/hæd/","gloss":"teve, tinha"},{"surface":"a","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"quick","pos":"adjective","ipa":"/kwɪk/","gloss":"rápido"},{"surface":"look","pos":"noun","ipa":"/lʊk/","gloss":"olhada"},{"surface":"at","pos":"preposition","ipa":"/æt/","gloss":"em, às"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"report","pos":"verb","ipa":"/rɪˈpɔːrt/","gloss":"registrar, relatar"}]'::jsonb, NULL, NULL),
  ('unit-collocations-b2-02-06', 'lesson-collocations-b2-02', 6, 'sentence', 'Take your time, there is no rush.', 'Sem pressa, não há correria.', '/teɪk jʊr taɪm ðɛr ɪz noʊ rʌʃ/', '"Take your time" = não se apresse.', '[]'::jsonb, '[{"surface":"Take","pos":"verb","ipa":"/teɪk/","gloss":"pegar, levar"},{"surface":"your","pos":"determiner","ipa":"/jʊr/","gloss":"seu, sua"},{"surface":"time","pos":"noun","ipa":"/taɪm/","gloss":"vez; hora"},{"surface":"there","pos":"adverb","ipa":"/ðɛr/","gloss":"lá"},{"surface":"is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"no","pos":"determiner","ipa":"/noʊ/","gloss":"nenhum; não"},{"surface":"rush","pos":"noun","ipa":"/rʌʃ/","gloss":"pressa, correria"}]'::jsonb, NULL, NULL),
  ('unit-collocations-b2-02-07', 'lesson-collocations-b2-02', 7, 'sentence', 'He took a long walk after dinner.', 'Ele deu uma longa caminhada depois do jantar.', '/hiː tʊk ə lɔːŋ wɔːk ˈæftər ˈdɪnər/', '"Take a walk" = dar uma caminhada.', '[]'::jsonb, '[{"surface":"He","pos":"pronoun","ipa":"/hiː/","gloss":"ele"},{"surface":"took","pos":"verb","ipa":"/tʊk/","gloss":"pegou, levou"},{"surface":"a","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"long","pos":"adjective","ipa":"/lɔːŋ/","gloss":"longo, muito (tempo)"},{"surface":"walk","pos":"noun","ipa":"/wɔːk/","gloss":"caminhada; andar"},{"surface":"after","pos":"preposition","ipa":"/ˈæftər/","gloss":"depois de"},{"surface":"dinner","pos":"noun","ipa":"/ˈdɪnər/","gloss":"jantar"}]'::jsonb, NULL, NULL),
  ('unit-collocations-b2-02-08', 'lesson-collocations-b2-02', 8, 'sentence', 'It takes about an hour to get there.', 'Leva cerca de uma hora para chegar lá.', '/ɪt teɪks əˈbaʊt ən ˈaʊər tuː ɡɛt ðɛr/', '"It takes" + tempo = leva tanto tempo.', '[]'::jsonb, '[{"surface":"It","pos":"pronoun","ipa":"/ɪt/","gloss":"isso, ele, ela"},{"surface":"takes","pos":"verb","ipa":"/teɪks/","gloss":"pega, leva; decola"},{"surface":"about","pos":"preposition","ipa":"/əˈbaʊt/","gloss":"sobre"},{"surface":"an","pos":"determiner","ipa":"/ən/","gloss":"um, uma"},{"surface":"hour","pos":"noun","ipa":"/ˈaʊər/","gloss":"hora"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"get","pos":"verb","ipa":"/ɡɛt/","gloss":"conseguir, chegar"},{"surface":"there","pos":"adverb","ipa":"/ðɛr/","gloss":"lá"}]'::jsonb, NULL, NULL),
  ('unit-collocations-b2-02-09', 'lesson-collocations-b2-02', 9, 'sentence', 'I need to get some rest.', 'Preciso descansar um pouco.', '/aɪ niːd tuː ɡɛt sʌm rɛst/', '"Get some rest" = descansar; "get" aqui significa conseguir ter.', '[]'::jsonb, '[{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"need","pos":"verb","ipa":"/niːd/","gloss":"precisar"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"get","pos":"verb","ipa":"/ɡɛt/","gloss":"conseguir, chegar"},{"surface":"some","pos":"determiner","ipa":"/sʌm/","gloss":"algumas"},{"surface":"rest","pos":"verb","ipa":"/rɛst/","gloss":"descansar"}]'::jsonb, NULL, NULL),
  ('unit-collocations-b2-02-10', 'lesson-collocations-b2-02', 10, 'sentence', 'Did you get my message?', 'Você recebeu minha mensagem?', '/dɪd juː ɡɛt maɪ ˈmɛsɪdʒ/', '"Get" = receber.', '[]'::jsonb, '[{"surface":"Did","pos":"verb","ipa":"/dɪd/","gloss":"fez"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"get","pos":"verb","ipa":"/ɡɛt/","gloss":"conseguir, chegar"},{"surface":"my","pos":"determiner","ipa":"/maɪ/","gloss":"meu, minha"},{"surface":"message","pos":"noun","ipa":"/ˈmɛsɪdʒ/","gloss":"mensagem"}]'::jsonb, NULL, NULL)
INSERT INTO public.course_lessons (id, course_id, chapter_number, title, description)
INSERT INTO public.course_units (id, lesson_id, order_index, kind, text, translation_pt, ipa, explanation_note, syntax_groups, annotations, example_en, example_pt)
VALUES
  ('unit-collocations-b2-03-01', 'lesson-collocations-b2-03', 1, 'sentence', 'We had heavy rain all weekend.', 'Choveu forte o fim de semana inteiro.', '/wiː hæd ˈhɛvi reɪn ɔːl ˈwiːkɛnd/', '"Heavy rain": a chuva é "pesada", nunca "strong rain".', '[]'::jsonb, '[{"surface":"We","pos":"pronoun","ipa":"/wiː/","gloss":"nós, a gente"},{"surface":"had","pos":"verb","ipa":"/hæd/","gloss":"teve, tinha"},{"surface":"heavy","pos":"adjective","ipa":"/ˈhɛvi/","gloss":"pesado"},{"surface":"rain","pos":"verb","ipa":"/reɪn/","gloss":"chover; chuva"},{"surface":"all","pos":"determiner","ipa":"/ɔːl/","gloss":"tudo, todos"},{"surface":"weekend","pos":"noun","ipa":"/ˈwiːkɛnd/","gloss":"fim de semana"}]'::jsonb, NULL, NULL),
  ('unit-collocations-b2-03-02', 'lesson-collocations-b2-03', 2, 'sentence', 'I like my coffee strong and black.', 'Gosto do meu café forte e puro.', '/aɪ laɪk maɪ ˈkɔːfi strɔːŋ ænd blæk/', '"Strong coffee" = café forte.', '[]'::jsonb, '[{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"like","pos":"verb","ipa":"/laɪk/","gloss":"gostar"},{"surface":"my","pos":"determiner","ipa":"/maɪ/","gloss":"meu, minha"},{"surface":"coffee","pos":"noun","ipa":"/ˈkɔːfi/","gloss":"café"},{"surface":"strong","pos":"adjective","ipa":"/strɔːŋ/","gloss":"forte"},{"surface":"and","pos":"conjunction","ipa":"/ænd/","gloss":"e"},{"surface":"black","pos":"adjective","ipa":"/blæk/","gloss":"preto"}]'::jsonb, NULL, NULL),
  ('unit-collocations-b2-03-03', 'lesson-collocations-b2-03', 3, 'sentence', 'She fell into a deep sleep.', 'Ela caiu num sono profundo.', '/ʃiː fɛl ˈɪntuː ə diːp sliːp/', '"Deep sleep" = sono profundo.', '[]'::jsonb, '[{"surface":"She","pos":"pronoun","ipa":"/ʃiː/","gloss":"ela"},{"surface":"fell","pos":"verb","ipa":"/fɛl/","gloss":"caiu"},{"surface":"into","pos":"preposition","ipa":"/ˈɪntuː/","gloss":"para dentro de"},{"surface":"a","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"deep","pos":"adjective","ipa":"/diːp/","gloss":"profundo"},{"surface":"sleep","pos":"verb","ipa":"/sliːp/","gloss":"dormir"}]'::jsonb, NULL, NULL),
  ('unit-collocations-b2-03-04', 'lesson-collocations-b2-03', 4, 'sentence', 'There was heavy traffic on the highway.', 'Havia trânsito pesado na rodovia.', '/ðɛr wɑːz ˈhɛvi ˈtræfɪk ɑːn ðə ˈhaɪweɪ/', '"Heavy traffic" = trânsito pesado.', '[]'::jsonb, '[{"surface":"There","pos":"adverb","ipa":"/ðɛr/","gloss":"lá"},{"surface":"was","pos":"verb","ipa":"/wɑːz/","gloss":"foi, estava"},{"surface":"heavy","pos":"adjective","ipa":"/ˈhɛvi/","gloss":"pesado"},{"surface":"traffic","pos":"noun","ipa":"/ˈtræfɪk/","gloss":"trânsito"},{"surface":"on","pos":"preposition","ipa":"/ɑːn/","gloss":"em, sobre"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"highway","pos":"noun","ipa":"/ˈhaɪweɪ/","gloss":"rodovia"}]'::jsonb, NULL, NULL),
  ('unit-collocations-b2-03-05', 'lesson-collocations-b2-03', 5, 'sentence', 'He has a strong accent.', 'Ele tem um sotaque carregado.', '/hiː hæz ə strɔːŋ ˈæksɛnt/', '"Strong accent" = sotaque forte.', '[]'::jsonb, '[{"surface":"He","pos":"pronoun","ipa":"/hiː/","gloss":"ele"},{"surface":"has","pos":"verb","ipa":"/hæz/","gloss":"tem (he/she/it)"},{"surface":"a","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"strong","pos":"adjective","ipa":"/strɔːŋ/","gloss":"forte"},{"surface":"accent","pos":"noun","ipa":"/ˈæksɛnt/","gloss":"sotaque"}]'::jsonb, NULL, NULL),
  ('unit-collocations-b2-03-06', 'lesson-collocations-b2-03', 6, 'sentence', 'That was a close call.', 'Foi por pouco.', '/ðæt wɑːz ə kloʊz kɔːl/', '"Close call" = escapar por pouco de um problema.', '[]'::jsonb, '[{"surface":"That","pos":"pronoun","ipa":"/ðæt/","gloss":"isso, aquilo"},{"surface":"was","pos":"verb","ipa":"/wɑːz/","gloss":"foi, estava"},{"surface":"a","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"close","pos":"verb","ipa":"/kloʊz/","gloss":"fechar"},{"surface":"call","pos":"noun","ipa":"/kɔːl/","gloss":"chamada, call"}]'::jsonb, NULL, NULL),
  ('unit-collocations-b2-03-07', 'lesson-collocations-b2-03', 7, 'sentence', 'They made a big mistake.', 'Eles cometeram um grande erro.', '/ðeɪ meɪd ə bɪɡ mɪˈsteɪk/', '"Big mistake": o erro é grande, não "large".', '[]'::jsonb, '[{"surface":"They","pos":"pronoun","ipa":"/ðeɪ/","gloss":"eles, elas"},{"surface":"made","pos":"verb","ipa":"/meɪd/","gloss":"fez, feito"},{"surface":"a","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"big","pos":"adjective","ipa":"/bɪɡ/","gloss":"grande"},{"surface":"mistake","pos":"noun","ipa":"/mɪˈsteɪk/","gloss":"erro"}]'::jsonb, NULL, NULL),
  ('unit-collocations-b2-03-08', 'lesson-collocations-b2-03', 8, 'sentence', 'I have a bad cold and a sore throat.', 'Estou com um resfriado forte e dor de garganta.', '/aɪ hæv ə bæd koʊld ænd ə sɔːr θroʊt/', '"Bad cold" = resfriado forte.', '[]'::jsonb, '[{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"have","pos":"verb","ipa":"/hæv/","gloss":"ter"},{"surface":"a","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"bad","pos":"adjective","ipa":"/bæd/","gloss":"ruim"},{"surface":"cold","pos":"noun","ipa":"/koʊld/","gloss":"resfriado; frio"},{"surface":"and","pos":"conjunction","ipa":"/ænd/","gloss":"e"},{"surface":"a","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"sore","pos":"adjective","ipa":"/sɔːr/","gloss":"dolorido"},{"surface":"throat","pos":"noun","ipa":"/θroʊt/","gloss":"garganta"}]'::jsonb, NULL, NULL),
  ('unit-collocations-b2-03-09', 'lesson-collocations-b2-03', 9, 'sentence', 'It was a narrow escape.', 'Foi uma fuga por um triz.', '/ɪt wɑːz ə ˈnæroʊ ɪˈskeɪp/', '"Narrow escape" = escapar por pouco.', '[]'::jsonb, '[{"surface":"It","pos":"pronoun","ipa":"/ɪt/","gloss":"isso, ele, ela"},{"surface":"was","pos":"verb","ipa":"/wɑːz/","gloss":"foi, estava"},{"surface":"a","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"narrow","pos":"adjective","ipa":"/ˈnæroʊ/","gloss":"estreito"},{"surface":"escape","pos":"noun","ipa":"/ɪˈskeɪp/","gloss":"fuga"}]'::jsonb, NULL, NULL),
  ('unit-collocations-b2-03-10', 'lesson-collocations-b2-03', 10, 'sentence', 'We need fresh air and some good news.', 'Precisamos de ar fresco e de boas notícias.', '/wiː niːd frɛʃ ɛr ænd sʌm ɡʊd nuːz/', '"Fresh air" = ar puro.', '[]'::jsonb, '[{"surface":"We","pos":"pronoun","ipa":"/wiː/","gloss":"nós, a gente"},{"surface":"need","pos":"verb","ipa":"/niːd/","gloss":"precisar"},{"surface":"fresh","pos":"adjective","ipa":"/frɛʃ/","gloss":"fresco"},{"surface":"air","pos":"noun","ipa":"/ɛr/","gloss":"ar"},{"surface":"and","pos":"conjunction","ipa":"/ænd/","gloss":"e"},{"surface":"some","pos":"determiner","ipa":"/sʌm/","gloss":"algumas"},{"surface":"good","pos":"adjective","ipa":"/ɡʊd/","gloss":"bom"},{"surface":"news","pos":"noun","ipa":"/nuːz/","gloss":"notícia(s)"}]'::jsonb, NULL, NULL)
INSERT INTO public.course_lessons (id, course_id, chapter_number, title, description)
INSERT INTO public.course_units (id, lesson_id, order_index, kind, text, translation_pt, ipa, explanation_note, syntax_groups, annotations, example_en, example_pt)
VALUES
  ('unit-collocations-b2-04-01', 'lesson-collocations-b2-04', 1, 'sentence', 'We need to meet the deadline on Friday.', 'Precisamos cumprir o prazo de sexta.', '/wiː niːd tuː miːt ðə ˈdɛdlaɪn ɑːn ˈfraɪdeɪ/', '"Meet a deadline" = cumprir um prazo.', '[]'::jsonb, '[{"surface":"We","pos":"pronoun","ipa":"/wiː/","gloss":"nós, a gente"},{"surface":"need","pos":"verb","ipa":"/niːd/","gloss":"precisar"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"meet","pos":"verb","ipa":"/miːt/","gloss":"encontrar"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"deadline","pos":"noun","ipa":"/ˈdɛdlaɪn/","gloss":"prazo"},{"surface":"on","pos":"preposition","ipa":"/ɑːn/","gloss":"em, sobre"},{"surface":"Friday","pos":"proper noun","ipa":"/ˈfraɪdeɪ/","gloss":"sexta-feira"}]'::jsonb, NULL, NULL),
  ('unit-collocations-b2-04-02', 'lesson-collocations-b2-04', 2, 'sentence', 'She runs a small design studio.', 'Ela toca um pequeno estúdio de design.', '/ʃiː rʌnz ə smɔːl dɪˈzaɪn ˈstuːdioʊ/', '"Run a business" = administrar um negócio.', '[]'::jsonb, '[{"surface":"She","pos":"pronoun","ipa":"/ʃiː/","gloss":"ela"},{"surface":"runs","pos":"verb","ipa":"/rʌnz/","gloss":"administra; corre"},{"surface":"a","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"small","pos":"adjective","ipa":"/smɔːl/","gloss":"pequeno"},{"surface":"design","pos":"noun","ipa":"/dɪˈzaɪn/","gloss":"design"},{"surface":"studio","pos":"noun","ipa":"/ˈstuːdioʊ/","gloss":"estúdio"}]'::jsonb, NULL, NULL),
  ('unit-collocations-b2-04-03', 'lesson-collocations-b2-04', 3, 'sentence', 'The two companies reached an agreement.', 'As duas empresas chegaram a um acordo.', '/ðə tuː ˈkʌmpəniz riːtʃt ən əˈɡriːmənt/', '"Reach an agreement" = chegar a um acordo.', '[]'::jsonb, '[{"surface":"The","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"two","pos":"numeral","ipa":"/tuː/","gloss":"dois"},{"surface":"companies","pos":"noun","ipa":"/ˈkʌmpəniz/","gloss":"empresas"},{"surface":"reached","pos":"verb","ipa":"/riːtʃt/","gloss":"alcançou"},{"surface":"an","pos":"determiner","ipa":"/ən/","gloss":"um, uma"},{"surface":"agreement","pos":"noun","ipa":"/əˈɡriːmənt/","gloss":"acordo"}]'::jsonb, NULL, NULL),
  ('unit-collocations-b2-04-04', 'lesson-collocations-b2-04', 4, 'sentence', 'He gave a presentation to the board.', 'Ele fez uma apresentação para a diretoria.', '/hiː ɡeɪv ə ˌprɛzənˈteɪʃən tuː ðə bɔːrd/', '"Give a presentation": em inglês se "dá" uma apresentação.', '[]'::jsonb, '[{"surface":"He","pos":"pronoun","ipa":"/hiː/","gloss":"ele"},{"surface":"gave","pos":"verb","ipa":"/ɡeɪv/","gloss":"deu"},{"surface":"a","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"presentation","pos":"noun","ipa":"/ˌprɛzənˈteɪʃən/","gloss":"apresentação"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"board","pos":"noun","ipa":"/bɔːrd/","gloss":"diretoria, conselho"}]'::jsonb, NULL, NULL),
  ('unit-collocations-b2-04-05', 'lesson-collocations-b2-04', 5, 'sentence', 'Can we schedule a meeting for next week?', 'Podemos marcar uma reunião para a semana que vem?', '/kæn wiː ˈskɛdʒuːl ə ˈmiːtɪŋ fɔːr nɛkst wiːk/', '"Schedule a meeting" = marcar uma reunião.', '[]'::jsonb, '[{"surface":"Can","pos":"auxiliary verb","ipa":"/kæn/","gloss":"poder"},{"surface":"we","pos":"pronoun","ipa":"/wiː/","gloss":"nós, a gente"},{"surface":"schedule","pos":"noun","ipa":"/ˈskɛdʒuːl/","gloss":"horário, agenda"},{"surface":"a","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"meeting","pos":"noun","ipa":"/ˈmiːtɪŋ/","gloss":"reunião"},{"surface":"for","pos":"preposition","ipa":"/fɔːr/","gloss":"para, por"},{"surface":"next","pos":"adjective","ipa":"/nɛkst/","gloss":"próximo"},{"surface":"week","pos":"noun","ipa":"/wiːk/","gloss":"semana"}]'::jsonb, NULL, NULL),
  ('unit-collocations-b2-04-06', 'lesson-collocations-b2-04', 6, 'sentence', 'I will send you a follow-up email.', 'Vou te enviar um e-mail de acompanhamento.', '/aɪ wɪl sɛnd juː ə ˈfɑːloʊ ʌp ˈiːmeɪl/', '"Send a follow-up" = enviar uma mensagem de retomada.', '[]'::jsonb, '[{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"will","pos":"modal verb","ipa":"/wɪl/","gloss":"marca de futuro"},{"surface":"send","pos":"verb","ipa":"/sɛnd/","gloss":"enviar, mandar"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"a","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"follow-up","pos":"noun","ipa":"/ˈfɑːloʊ ʌp/","gloss":"acompanhamento, retomada"},{"surface":"email","pos":"noun","ipa":"/ˈiːmeɪl/","gloss":"e-mail"}]'::jsonb, NULL, NULL),
  ('unit-collocations-b2-04-07', 'lesson-collocations-b2-04', 7, 'sentence', 'The team set a clear goal for the quarter.', 'A equipe definiu uma meta clara para o trimestre.', '/ðə tiːm sɛt ə klɪr ɡoʊl fɔːr ðə ˈkwɔːrtər/', '"Set a goal": a meta é "colocada", não "made".', '[]'::jsonb, '[{"surface":"The","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"team","pos":"noun","ipa":"/tiːm/","gloss":"time, equipe"},{"surface":"set","pos":"verb","ipa":"/sɛt/","gloss":"definir"},{"surface":"a","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"clear","pos":"adjective","ipa":"/klɪr/","gloss":"claro"},{"surface":"goal","pos":"noun","ipa":"/ɡoʊl/","gloss":"meta"},{"surface":"for","pos":"preposition","ipa":"/fɔːr/","gloss":"para, por"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"quarter","pos":"noun","ipa":"/ˈkwɔːrtər/","gloss":"quarto (15 minutos)"}]'::jsonb, NULL, NULL),
  ('unit-collocations-b2-04-08', 'lesson-collocations-b2-04', 8, 'sentence', 'We should look into this problem.', 'Devemos investigar esse problema.', '/wiː ʃʊd lʊk ˈɪntuː ðɪs ˈprɑːbləm/', '"Look into" = investigar, analisar.', '[]'::jsonb, '[{"surface":"We","pos":"pronoun","ipa":"/wiː/","gloss":"nós, a gente"},{"surface":"should","pos":"modal verb","ipa":"/ʃʊd/","gloss":"deveria"},{"surface":"look","pos":"noun","ipa":"/lʊk/","gloss":"olhada"},{"surface":"into","pos":"preposition","ipa":"/ˈɪntuː/","gloss":"para dentro de"},{"surface":"this","pos":"determiner","ipa":"/ðɪs/","gloss":"este, esta, isso"},{"surface":"problem","pos":"noun","ipa":"/ˈprɑːbləm/","gloss":"problema"}]'::jsonb, NULL, NULL),
  ('unit-collocations-b2-04-09', 'lesson-collocations-b2-04', 9, 'sentence', 'She handled the complaint very well.', 'Ela lidou muito bem com a reclamação.', '/ʃiː ˈhændəld ðə kəmˈpleɪnt ˈvɛri wɛl/', '"Handle a complaint" = lidar com uma reclamação.', '[]'::jsonb, '[{"surface":"She","pos":"pronoun","ipa":"/ʃiː/","gloss":"ela"},{"surface":"handled","pos":"verb","ipa":"/ˈhændəld/","gloss":"lidou com"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"complaint","pos":"noun","ipa":"/kəmˈpleɪnt/","gloss":"reclamação"},{"surface":"very","pos":"adverb","ipa":"/ˈvɛri/","gloss":"muito"},{"surface":"well","pos":"adverb","ipa":"/wɛl/","gloss":"bem"}]'::jsonb, NULL, NULL),
  ('unit-collocations-b2-04-10', 'lesson-collocations-b2-04', 10, 'sentence', 'Please keep me in the loop.', 'Me mantenha informado, por favor.', '/pliːz kiːp miː ɪn ðə luːp/', '"Keep someone in the loop" = manter alguém por dentro.', '[]'::jsonb, '[{"surface":"Please","pos":"adverb","ipa":"/pliːz/","gloss":"por favor"},{"surface":"keep","pos":"verb","ipa":"/kiːp/","gloss":"manter"},{"surface":"me","pos":"pronoun","ipa":"/miː/","gloss":"me, mim"},{"surface":"in","pos":"preposition","ipa":"/ɪn/","gloss":"em, dentro de"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"loop","pos":"noun","ipa":"/luːp/","gloss":"circuito, laço"}]'::jsonb, NULL, NULL)
INSERT INTO public.course_lessons (id, course_id, chapter_number, title, description)
INSERT INTO public.course_units (id, lesson_id, order_index, kind, text, translation_pt, ipa, explanation_note, syntax_groups, annotations, example_en, example_pt)
VALUES
  ('unit-collocations-b2-05-01', 'lesson-collocations-b2-05', 1, 'sentence', 'I am deeply grateful for your help.', 'Sou profundamente grato pela sua ajuda.', '/aɪ æm ˈdiːpli ˈɡreɪtfəl fɔːr jʊr hɛlp/', '"Deeply grateful": emoções fortes pedem "deeply".', '[]'::jsonb, '[{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"am","pos":"auxiliary verb","ipa":"/æm/","gloss":"sou, estou"},{"surface":"deeply","pos":"adverb","ipa":"/ˈdiːpli/","gloss":"profundamente"},{"surface":"grateful","pos":"adjective","ipa":"/ˈɡreɪtfəl/","gloss":"grato"},{"surface":"for","pos":"preposition","ipa":"/fɔːr/","gloss":"para, por"},{"surface":"your","pos":"determiner","ipa":"/jʊr/","gloss":"seu, sua"},{"surface":"help","pos":"interjection","ipa":"/hɛlp/","gloss":"socorro; ajudar"}]'::jsonb, NULL, NULL),
  ('unit-collocations-b2-05-02', 'lesson-collocations-b2-05', 2, 'sentence', 'This restaurant is highly recommended.', 'Este restaurante é muito bem recomendado.', '/ðɪs ˈrɛstərɑːnt ɪz ˈhaɪli ˌrɛkəˈmɛndɪd/', '"Highly recommended" = fortemente recomendado.', '[]'::jsonb, '[{"surface":"This","pos":"determiner","ipa":"/ðɪs/","gloss":"este, esta, isso"},{"surface":"restaurant","pos":"noun","ipa":"/ˈrɛstərɑːnt/","gloss":"restaurante"},{"surface":"is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"highly","pos":"adverb","ipa":"/ˈhaɪli/","gloss":"altamente, muito"},{"surface":"recommended","pos":"verb","ipa":"/ˌrɛkəˈmɛndɪd/","gloss":"recomendado"}]'::jsonb, NULL, NULL),
  ('unit-collocations-b2-05-03', 'lesson-collocations-b2-05', 3, 'sentence', 'The two plans are completely different.', 'Os dois planos são completamente diferentes.', '/ðə tuː plænz ɑːr kəmˈpliːtli ˈdɪfərənt/', '"Completely different" é a combinação natural.', '[]'::jsonb, '[{"surface":"The","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"two","pos":"numeral","ipa":"/tuː/","gloss":"dois"},{"surface":"plans","pos":"noun","ipa":"/plænz/","gloss":"planos"},{"surface":"are","pos":"auxiliary verb","ipa":"/ɑːr/","gloss":"são, estão"},{"surface":"completely","pos":"adverb","ipa":"/kəmˈpliːtli/","gloss":"completamente"},{"surface":"different","pos":"adjective","ipa":"/ˈdɪfərənt/","gloss":"diferente"}]'::jsonb, NULL, NULL),
  ('unit-collocations-b2-05-04', 'lesson-collocations-b2-05', 4, 'sentence', 'She was bitterly disappointed.', 'Ela ficou amargamente decepcionada.', '/ʃiː wɑːz ˈbɪtərli ˌdɪsəˈpɔɪntɪd/', '"Bitterly disappointed" = muito decepcionada.', '[]'::jsonb, '[{"surface":"She","pos":"pronoun","ipa":"/ʃiː/","gloss":"ela"},{"surface":"was","pos":"verb","ipa":"/wɑːz/","gloss":"foi, estava"},{"surface":"bitterly","pos":"adverb","ipa":"/ˈbɪtərli/","gloss":"amargamente"},{"surface":"disappointed","pos":"adjective","ipa":"/ˌdɪsəˈpɔɪntɪd/","gloss":"decepcionado"}]'::jsonb, NULL, NULL),
  ('unit-collocations-b2-05-05', 'lesson-collocations-b2-05', 5, 'sentence', 'He is fully aware of the risks.', 'Ele tem plena consciência dos riscos.', '/hiː ɪz ˈfʊli əˈwɛr ʌv ðə rɪsks/', '"Fully aware" = plenamente ciente.', '[]'::jsonb, '[{"surface":"He","pos":"pronoun","ipa":"/hiː/","gloss":"ele"},{"surface":"is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"fully","pos":"adverb","ipa":"/ˈfʊli/","gloss":"totalmente"},{"surface":"aware","pos":"adjective","ipa":"/əˈwɛr/","gloss":"ciente, consciente"},{"surface":"of","pos":"preposition","ipa":"/ʌv/","gloss":"de"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"risks","pos":"noun","ipa":"/rɪsks/","gloss":"riscos"}]'::jsonb, NULL, NULL),
  ('unit-collocations-b2-05-06', 'lesson-collocations-b2-05', 6, 'sentence', 'It is perfectly normal to feel nervous.', 'É perfeitamente normal ficar nervoso.', '/ɪt ɪz ˈpɜːrfɪktli ˈnɔːrməl tuː fiːl ˈnɜːrvəs/', '"Perfectly normal" tranquiliza.', '[]'::jsonb, '[{"surface":"It","pos":"pronoun","ipa":"/ɪt/","gloss":"isso, ele, ela"},{"surface":"is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"perfectly","pos":"adverb","ipa":"/ˈpɜːrfɪktli/","gloss":"perfeitamente"},{"surface":"normal","pos":"adjective","ipa":"/ˈnɔːrməl/","gloss":"normal"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"feel","pos":"verb","ipa":"/fiːl/","gloss":"sentir"},{"surface":"nervous","pos":"adjective","ipa":"/ˈnɜːrvəs/","gloss":"nervoso, ansioso"}]'::jsonb, NULL, NULL),
  ('unit-collocations-b2-05-07', 'lesson-collocations-b2-05', 7, 'sentence', 'The test was painfully slow.', 'O teste foi dolorosamente lento.', '/ðə tɛst wɑːz ˈpeɪnfəli sloʊ/', '"Painfully slow" = lento de dar agonia.', '[]'::jsonb, '[{"surface":"The","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"test","pos":"noun","ipa":"/tɛst/","gloss":"exame, teste"},{"surface":"was","pos":"verb","ipa":"/wɑːz/","gloss":"foi, estava"},{"surface":"painfully","pos":"adverb","ipa":"/ˈpeɪnfəli/","gloss":"dolorosamente"},{"surface":"slow","pos":"adjective","ipa":"/sloʊ/","gloss":"lento"}]'::jsonb, NULL, NULL),
  ('unit-collocations-b2-05-08', 'lesson-collocations-b2-05', 8, 'sentence', 'I am utterly exhausted.', 'Estou absolutamente exausto.', '/aɪ æm ˈʌtərli ɪɡˈzɔːstɪd/', '"Utterly" combina com adjetivos extremos: exhausted, impossible.', '[]'::jsonb, '[{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"am","pos":"auxiliary verb","ipa":"/æm/","gloss":"sou, estou"},{"surface":"utterly","pos":"adverb","ipa":"/ˈʌtərli/","gloss":"totalmente, absolutamente"},{"surface":"exhausted","pos":"adjective","ipa":"/ɪɡˈzɔːstɪd/","gloss":"exausto"}]'::jsonb, NULL, NULL),
  ('unit-collocations-b2-05-09', 'lesson-collocations-b2-05', 9, 'sentence', 'The rules are strictly enforced here.', 'As regras são aplicadas com rigor aqui.', '/ðə ruːlz ɑːr ˈstrɪktli ɪnˈfɔːrst hɪr/', '"Strictly enforced" = aplicado com rigor.', '[]'::jsonb, '[{"surface":"The","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"rules","pos":"noun","ipa":"/ruːlz/","gloss":"regras"},{"surface":"are","pos":"auxiliary verb","ipa":"/ɑːr/","gloss":"são, estão"},{"surface":"strictly","pos":"adverb","ipa":"/ˈstrɪktli/","gloss":"estritamente, com rigor"},{"surface":"enforced","pos":"verb","ipa":"/ɪnˈfɔːrst/","gloss":"aplicado, imposto"},{"surface":"here","pos":"adverb","ipa":"/hɪr/","gloss":"aqui"}]'::jsonb, NULL, NULL),
  ('unit-collocations-b2-05-10', 'lesson-collocations-b2-05', 10, 'sentence', 'We are fairly sure it will work.', 'Temos bastante certeza de que vai funcionar.', '/wiː ɑːr ˈfɛrli ʃʊr ɪt wɪl wɜːrk/', '"Fairly" suaviza: bastante, mas não totalmente.', '[]'::jsonb, '[{"surface":"We","pos":"pronoun","ipa":"/wiː/","gloss":"nós, a gente"},{"surface":"are","pos":"auxiliary verb","ipa":"/ɑːr/","gloss":"são, estão"},{"surface":"fairly","pos":"adverb","ipa":"/ˈfɛrli/","gloss":"bastante, razoavelmente"},{"surface":"sure","pos":"adjective","ipa":"/ʃʊr/","gloss":"claro; certo"},{"surface":"it","pos":"pronoun","ipa":"/ɪt/","gloss":"isso, ele, ela"},{"surface":"will","pos":"modal verb","ipa":"/wɪl/","gloss":"marca de futuro"},{"surface":"work","pos":"noun","ipa":"/wɜːrk/","gloss":"trabalho"}]'::jsonb, NULL, NULL)
INSERT INTO public.course_lessons (id, course_id, chapter_number, title, description)
INSERT INTO public.course_units (id, lesson_id, order_index, kind, text, translation_pt, ipa, explanation_note, syntax_groups, annotations, example_en, example_pt)
VALUES
  ('unit-collocations-b2-06-01', 'lesson-collocations-b2-06', 1, 'sentence', 'She makes a good living as a nurse.', 'Ela ganha bem como enfermeira.', '/ʃiː meɪks ə ɡʊd ˈlɪvɪŋ æz ə nɜːrs/', '"Make a living" = ganhar a vida.', '[]'::jsonb, '[{"surface":"She","pos":"pronoun","ipa":"/ʃiː/","gloss":"ela"},{"surface":"makes","pos":"verb","ipa":"/meɪks/","gloss":"faz"},{"surface":"a","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"good","pos":"adjective","ipa":"/ɡʊd/","gloss":"bom"},{"surface":"living","pos":"adjective","ipa":"/ˈlɪvɪŋ/","gloss":"de estar"},{"surface":"as","pos":"conjunction","ipa":"/æz/","gloss":"como"},{"surface":"a","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"nurse","pos":"noun","ipa":"/nɜːrs/","gloss":"enfermeiro"}]'::jsonb, NULL, NULL),
  ('unit-collocations-b2-06-02', 'lesson-collocations-b2-06', 2, 'sentence', 'I cannot afford a new car right now.', 'Não tenho condições de comprar um carro novo agora.', '/aɪ ˈkænɑːt əˈfɔːrd ə nuː kɑːr raɪt naʊ/', '"Afford" = ter dinheiro para pagar.', '[]'::jsonb, '[{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"cannot","pos":"verb","ipa":"/ˈkænɑːt/","gloss":"não posso, não consigo"},{"surface":"afford","pos":"verb","ipa":"/əˈfɔːrd/","gloss":"ter condição de pagar"},{"surface":"a","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"new","pos":"adjective","ipa":"/nuː/","gloss":"novo"},{"surface":"car","pos":"noun","ipa":"/kɑːr/","gloss":"carro"},{"surface":"right","pos":"adverb","ipa":"/raɪt/","gloss":"bem; né? (right?)"},{"surface":"now","pos":"adverb","ipa":"/naʊ/","gloss":"agora"}]'::jsonb, NULL, NULL),
  ('unit-collocations-b2-06-03', 'lesson-collocations-b2-06', 3, 'sentence', 'We are trying to save money for a trip.', 'Estamos tentando economizar para uma viagem.', '/wiː ɑːr ˈtraɪɪŋ tuː seɪv ˈmʌni fɔːr ə trɪp/', '"Save money" = poupar dinheiro.', '[]'::jsonb, '[{"surface":"We","pos":"pronoun","ipa":"/wiː/","gloss":"nós, a gente"},{"surface":"are","pos":"auxiliary verb","ipa":"/ɑːr/","gloss":"são, estão"},{"surface":"trying","pos":"verb","ipa":"/ˈtraɪɪŋ/","gloss":"tentando"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"save","pos":"verb","ipa":"/seɪv/","gloss":"economizar, salvar"},{"surface":"money","pos":"noun","ipa":"/ˈmʌni/","gloss":"dinheiro"},{"surface":"for","pos":"preposition","ipa":"/fɔːr/","gloss":"para, por"},{"surface":"a","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"trip","pos":"noun","ipa":"/trɪp/","gloss":"viagem"}]'::jsonb, NULL, NULL),
  ('unit-collocations-b2-06-04', 'lesson-collocations-b2-06', 4, 'sentence', 'He ran up a huge debt.', 'Ele acumulou uma dívida enorme.', '/hiː ræn ʌp ə hjuːdʒ dɛt/', '"Run up a debt" = ir acumulando dívida.', '[]'::jsonb, '[{"surface":"He","pos":"pronoun","ipa":"/hiː/","gloss":"ele"},{"surface":"ran","pos":"verb","ipa":"/ræn/","gloss":"correu"},{"surface":"up","pos":"particle","ipa":"/ʌp/","gloss":"(partícula: up)"},{"surface":"a","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"huge","pos":"adjective","ipa":"/hjuːdʒ/","gloss":"enorme"},{"surface":"debt","pos":"noun","ipa":"/dɛt/","gloss":"dívida"}]'::jsonb, NULL, NULL),
  ('unit-collocations-b2-06-05', 'lesson-collocations-b2-06', 5, 'sentence', 'The company made a profit this year.', 'A empresa teve lucro este ano.', '/ðə ˈkʌmpəni meɪd ə ˈprɑːfɪt ðɪs jɪr/', '"Make a profit" = ter lucro.', '[]'::jsonb, '[{"surface":"The","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"company","pos":"noun","ipa":"/ˈkʌmpəni/","gloss":"empresa"},{"surface":"made","pos":"verb","ipa":"/meɪd/","gloss":"fez, feito"},{"surface":"a","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"profit","pos":"noun","ipa":"/ˈprɑːfɪt/","gloss":"lucro"},{"surface":"this","pos":"determiner","ipa":"/ðɪs/","gloss":"este, esta, isso"},{"surface":"year","pos":"noun","ipa":"/jɪr/","gloss":"ano"}]'::jsonb, NULL, NULL),
  ('unit-collocations-b2-06-06', 'lesson-collocations-b2-06', 6, 'sentence', 'Prices have gone up again.', 'Os preços subiram de novo.', '/ˈpraɪsɪz hæv ɡɔːn ʌp əˈɡɛn/', '"Prices go up" = subir; o oposto é "go down".', '[]'::jsonb, '[{"surface":"Prices","pos":"noun","ipa":"/ˈpraɪsɪz/","gloss":"preços"},{"surface":"have","pos":"verb","ipa":"/hæv/","gloss":"ter"},{"surface":"gone","pos":"verb","ipa":"/ɡɔːn/","gloss":"ido (particípio de go)"},{"surface":"up","pos":"particle","ipa":"/ʌp/","gloss":"(partícula: up)"},{"surface":"again","pos":"adverb","ipa":"/əˈɡɛn/","gloss":"de novo"}]'::jsonb, NULL, NULL),
  ('unit-collocations-b2-06-07', 'lesson-collocations-b2-06', 7, 'sentence', 'How much do you charge for a lesson?', 'Quanto você cobra por uma aula?', '/haʊ mʌtʃ duː juː tʃɑːrdʒ fɔːr ə ˈlɛsən/', '"Charge" = cobrar, de quem vende.', '[]'::jsonb, '[{"surface":"How","pos":"adverb","ipa":"/haʊ/","gloss":"como"},{"surface":"much","pos":"adverb","ipa":"/mʌtʃ/","gloss":"quanto (how much)"},{"surface":"do","pos":"auxiliary verb","ipa":"/duː/","gloss":"fazer; auxiliar de pergunta"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"charge","pos":"noun","ipa":"/tʃɑːrdʒ/","gloss":"cobrança"},{"surface":"for","pos":"preposition","ipa":"/fɔːr/","gloss":"para, por"},{"surface":"a","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"lesson","pos":"noun","ipa":"/ˈlɛsən/","gloss":"aula, lição"}]'::jsonb, NULL, NULL),
  ('unit-collocations-b2-06-08', 'lesson-collocations-b2-06', 8, 'sentence', 'I owe you ten dollars.', 'Devo dez dólares a você.', '/aɪ oʊ juː tɛn ˈdɑːlərz/', '"Owe" = dever dinheiro.', '[]'::jsonb, '[{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"owe","pos":"verb","ipa":"/oʊ/","gloss":"dever"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"ten","pos":"numeral","ipa":"/tɛn/","gloss":"dez"},{"surface":"dollars","pos":"noun","ipa":"/ˈdɑːlərz/","gloss":"dólares"}]'::jsonb, NULL, NULL),
  ('unit-collocations-b2-06-09', 'lesson-collocations-b2-06', 9, 'sentence', 'They pay a fair price for the work.', 'Eles pagam um preço justo pelo trabalho.', '/ðeɪ peɪ ə fɛr praɪs fɔːr ðə wɜːrk/', '"Fair price" = preço justo.', '[]'::jsonb, '[{"surface":"They","pos":"pronoun","ipa":"/ðeɪ/","gloss":"eles, elas"},{"surface":"pay","pos":"verb","ipa":"/peɪ/","gloss":"pagar"},{"surface":"a","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"fair","pos":"adjective","ipa":"/fɛr/","gloss":"justo"},{"surface":"price","pos":"noun","ipa":"/praɪs/","gloss":"preço"},{"surface":"for","pos":"preposition","ipa":"/fɔːr/","gloss":"para, por"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"work","pos":"noun","ipa":"/wɜːrk/","gloss":"trabalho"}]'::jsonb, NULL, NULL),
  ('unit-collocations-b2-06-10', 'lesson-collocations-b2-06', 10, 'sentence', 'We are on a tight budget this month.', 'Estamos com o orçamento apertado neste mês.', '/wiː ɑːr ɑːn ə taɪt ˈbʌdʒɪt ðɪs mʌnθ/', '"Tight budget" = orçamento apertado.', '[]'::jsonb, '[{"surface":"We","pos":"pronoun","ipa":"/wiː/","gloss":"nós, a gente"},{"surface":"are","pos":"auxiliary verb","ipa":"/ɑːr/","gloss":"são, estão"},{"surface":"on","pos":"preposition","ipa":"/ɑːn/","gloss":"em, sobre"},{"surface":"a","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"tight","pos":"adjective","ipa":"/taɪt/","gloss":"apertado"},{"surface":"budget","pos":"noun","ipa":"/ˈbʌdʒɪt/","gloss":"orçamento"},{"surface":"this","pos":"determiner","ipa":"/ðɪs/","gloss":"este, esta, isso"},{"surface":"month","pos":"noun","ipa":"/mʌnθ/","gloss":"mês"}]'::jsonb, NULL, NULL)
INSERT INTO public.course_lessons (id, course_id, chapter_number, title, description)
INSERT INTO public.course_units (id, lesson_id, order_index, kind, text, translation_pt, ipa, explanation_note, syntax_groups, annotations, example_en, example_pt)
VALUES
  ('unit-collocations-b2-07-01', 'lesson-collocations-b2-07', 1, 'sentence', 'Do not waste your time on this.', 'Não perca seu tempo com isso.', '/duː nɑːt weɪst jʊr taɪm ɑːn ðɪs/', '"Waste time" = perder, desperdiçar tempo.', '[]'::jsonb, '[{"surface":"Do","pos":"auxiliary verb","ipa":"/duː/","gloss":"fazer; auxiliar de pergunta"},{"surface":"not","pos":"particle","ipa":"/nɑːt/","gloss":"não"},{"surface":"waste","pos":"verb","ipa":"/weɪst/","gloss":"desperdiçar"},{"surface":"your","pos":"determiner","ipa":"/jʊr/","gloss":"seu, sua"},{"surface":"time","pos":"noun","ipa":"/taɪm/","gloss":"vez; hora"},{"surface":"on","pos":"preposition","ipa":"/ɑːn/","gloss":"em, sobre"},{"surface":"this","pos":"determiner","ipa":"/ðɪs/","gloss":"este, esta, isso"}]'::jsonb, NULL, NULL),
  ('unit-collocations-b2-07-02', 'lesson-collocations-b2-07', 2, 'sentence', 'Please pay attention to the instructions.', 'Preste atenção nas instruções, por favor.', '/pliːz peɪ əˈtɛnʃən tuː ðə ɪnˈstrʌkʃənz/', '"Pay attention": em inglês se "paga" atenção.', '[]'::jsonb, '[{"surface":"Please","pos":"adverb","ipa":"/pliːz/","gloss":"por favor"},{"surface":"pay","pos":"verb","ipa":"/peɪ/","gloss":"pagar"},{"surface":"attention","pos":"noun","ipa":"/əˈtɛnʃən/","gloss":"atenção"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"instructions","pos":"noun","ipa":"/ɪnˈstrʌkʃənz/","gloss":"instruções"}]'::jsonb, NULL, NULL),
  ('unit-collocations-b2-07-03', 'lesson-collocations-b2-07', 3, 'sentence', 'I spend most of my free time reading.', 'Passo a maior parte do meu tempo livre lendo.', '/aɪ spɛnd moʊst ʌv maɪ friː taɪm ˈriːdɪŋ/', '"Spend time" = passar tempo; "free time" = tempo livre.', '[]'::jsonb, '[{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"spend","pos":"verb","ipa":"/spɛnd/","gloss":"gastar, passar (tempo)"},{"surface":"most","pos":"determiner","ipa":"/moʊst/","gloss":"o máximo, a maioria"},{"surface":"of","pos":"preposition","ipa":"/ʌv/","gloss":"de"},{"surface":"my","pos":"determiner","ipa":"/maɪ/","gloss":"meu, minha"},{"surface":"free","pos":"adjective","ipa":"/friː/","gloss":"livre, disponível"},{"surface":"time","pos":"noun","ipa":"/taɪm/","gloss":"vez; hora"},{"surface":"reading","pos":"noun","ipa":"/ˈriːdɪŋ/","gloss":"leitura"}]'::jsonb, NULL, NULL),
  ('unit-collocations-b2-07-04', 'lesson-collocations-b2-07', 4, 'sentence', 'He lost track of time while studying.', 'Ele perdeu a noção do tempo enquanto estudava.', '/hiː lɔːst træk ʌv taɪm waɪl ˈstʌdiɪŋ/', '"Lose track of time" = perder a noção do tempo.', '[]'::jsonb, '[{"surface":"He","pos":"pronoun","ipa":"/hiː/","gloss":"ele"},{"surface":"lost","pos":"adjective","ipa":"/lɔːst/","gloss":"perdido; perdeu"},{"surface":"track","pos":"noun","ipa":"/træk/","gloss":"trilha, caminho"},{"surface":"of","pos":"preposition","ipa":"/ʌv/","gloss":"de"},{"surface":"time","pos":"noun","ipa":"/taɪm/","gloss":"vez; hora"},{"surface":"while","pos":"noun","ipa":"/waɪl/","gloss":"tempo (a while = um tempo)"},{"surface":"studying","pos":"verb","ipa":"/ˈstʌdiɪŋ/","gloss":"estudando"}]'::jsonb, NULL, NULL),
  ('unit-collocations-b2-07-05', 'lesson-collocations-b2-07', 5, 'sentence', 'We are running out of time.', 'Estamos ficando sem tempo.', '/wiː ɑːr ˈrʌnɪŋ aʊt ʌv taɪm/', '"Run out of" = acabar, esgotar.', '[]'::jsonb, '[{"surface":"We","pos":"pronoun","ipa":"/wiː/","gloss":"nós, a gente"},{"surface":"are","pos":"auxiliary verb","ipa":"/ɑːr/","gloss":"são, estão"},{"surface":"running","pos":"verb","ipa":"/ˈrʌnɪŋ/","gloss":"ficando (running late)"},{"surface":"out","pos":"adverb","ipa":"/aʊt/","gloss":"para fora"},{"surface":"of","pos":"preposition","ipa":"/ʌv/","gloss":"de"},{"surface":"time","pos":"noun","ipa":"/taɪm/","gloss":"vez; hora"}]'::jsonb, NULL, NULL),
  ('unit-collocations-b2-07-06', 'lesson-collocations-b2-07', 6, 'sentence', 'She kept track of every expense.', 'Ela anotou cada despesa.', '/ʃiː kɛpt træk ʌv ˈɛvri ɪkˈspɛns/', '"Keep track of" = acompanhar, controlar.', '[]'::jsonb, '[{"surface":"She","pos":"pronoun","ipa":"/ʃiː/","gloss":"ela"},{"surface":"kept","pos":"verb","ipa":"/kɛpt/","gloss":"guardou, manteve"},{"surface":"track","pos":"noun","ipa":"/træk/","gloss":"trilha, caminho"},{"surface":"of","pos":"preposition","ipa":"/ʌv/","gloss":"de"},{"surface":"every","pos":"determiner","ipa":"/ˈɛvri/","gloss":"todo, cada"},{"surface":"expense","pos":"noun","ipa":"/ɪkˈspɛns/","gloss":"despesa"}]'::jsonb, NULL, NULL),
  ('unit-collocations-b2-07-07', 'lesson-collocations-b2-07', 7, 'sentence', 'Can I save a seat for you?', 'Posso guardar um lugar para você?', '/kæn aɪ seɪv ə siːt fɔːr juː/', '"Save a seat" = guardar um lugar.', '[]'::jsonb, '[{"surface":"Can","pos":"auxiliary verb","ipa":"/kæn/","gloss":"poder"},{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"save","pos":"verb","ipa":"/seɪv/","gloss":"economizar, salvar"},{"surface":"a","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"seat","pos":"noun","ipa":"/siːt/","gloss":"assento"},{"surface":"for","pos":"preposition","ipa":"/fɔːr/","gloss":"para, por"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"}]'::jsonb, NULL, NULL),
  ('unit-collocations-b2-07-08', 'lesson-collocations-b2-07', 8, 'sentence', 'I have no time to spare today.', 'Não tenho tempo sobrando hoje.', '/aɪ hæv noʊ taɪm tuː spɛr təˈdeɪ/', '"Time to spare" = tempo de sobra.', '[]'::jsonb, '[{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"have","pos":"verb","ipa":"/hæv/","gloss":"ter"},{"surface":"no","pos":"determiner","ipa":"/noʊ/","gloss":"nenhum; não"},{"surface":"time","pos":"noun","ipa":"/taɪm/","gloss":"vez; hora"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"spare","pos":"adjective","ipa":"/spɛr/","gloss":"de sobra"},{"surface":"today","pos":"adverb","ipa":"/təˈdeɪ/","gloss":"hoje"}]'::jsonb, NULL, NULL),
  ('unit-collocations-b2-07-09', 'lesson-collocations-b2-07', 9, 'sentence', 'It is high time we left.', 'Já está na hora de a gente ir.', '/ɪt ɪz haɪ taɪm wiː lɛft/', '"High time" + passado = já passou da hora.', '[]'::jsonb, '[{"surface":"It","pos":"pronoun","ipa":"/ɪt/","gloss":"isso, ele, ela"},{"surface":"is","pos":"auxiliary verb","ipa":"/ɪz/","gloss":"é, está"},{"surface":"high","pos":"adjective","ipa":"/haɪ/","gloss":"alto"},{"surface":"time","pos":"noun","ipa":"/taɪm/","gloss":"vez; hora"},{"surface":"we","pos":"pronoun","ipa":"/wiː/","gloss":"nós, a gente"},{"surface":"left","pos":"adverb","ipa":"/lɛft/","gloss":"à esquerda"}]'::jsonb, NULL, NULL),
  ('unit-collocations-b2-07-10', 'lesson-collocations-b2-07', 10, 'sentence', 'Take the chance while you still can.', 'Aproveite a chance enquanto ainda pode.', '/teɪk ðə tʃæns waɪl juː stɪl kæn/', '"Take a chance" = arriscar, aproveitar a oportunidade.', '[]'::jsonb, '[{"surface":"Take","pos":"verb","ipa":"/teɪk/","gloss":"pegar, levar"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"chance","pos":"noun","ipa":"/tʃæns/","gloss":"chance, oportunidade"},{"surface":"while","pos":"noun","ipa":"/waɪl/","gloss":"tempo (a while = um tempo)"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"still","pos":"adverb","ipa":"/stɪl/","gloss":"ainda"},{"surface":"can","pos":"auxiliary verb","ipa":"/kæn/","gloss":"poder"}]'::jsonb, NULL, NULL)
INSERT INTO public.course_lessons (id, course_id, chapter_number, title, description)
INSERT INTO public.course_units (id, lesson_id, order_index, kind, text, translation_pt, ipa, explanation_note, syntax_groups, annotations, example_en, example_pt)
VALUES
  ('unit-collocations-b2-08-01', 'lesson-collocations-b2-08', 1, 'sentence', 'Can I raise a question about the schedule?', 'Posso levantar uma pergunta sobre o cronograma?', '/kæn aɪ reɪz ə ˈkwɛstʃən əˈbaʊt ðə ˈskɛdʒuːl/', '"Raise a question" = levantar uma questão.', '[]'::jsonb, '[{"surface":"Can","pos":"auxiliary verb","ipa":"/kæn/","gloss":"poder"},{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"raise","pos":"verb","ipa":"/reɪz/","gloss":"elevar, aumentar"},{"surface":"a","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"question","pos":"noun","ipa":"/ˈkwɛstʃən/","gloss":"pergunta"},{"surface":"about","pos":"preposition","ipa":"/əˈbaʊt/","gloss":"sobre"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"schedule","pos":"noun","ipa":"/ˈskɛdʒuːl/","gloss":"horário, agenda"}]'::jsonb, NULL, NULL),
  ('unit-collocations-b2-08-02', 'lesson-collocations-b2-08', 2, 'sentence', 'She made a good point during the meeting.', 'Ela fez uma boa colocação na reunião.', '/ʃiː meɪd ə ɡʊd pɔɪnt ˈdʊrɪŋ ðə ˈmiːtɪŋ/', '"Make a point" = argumentar, apontar algo.', '[]'::jsonb, '[{"surface":"She","pos":"pronoun","ipa":"/ʃiː/","gloss":"ela"},{"surface":"made","pos":"verb","ipa":"/meɪd/","gloss":"fez, feito"},{"surface":"a","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"good","pos":"adjective","ipa":"/ɡʊd/","gloss":"bom"},{"surface":"point","pos":"noun","ipa":"/pɔɪnt/","gloss":"ponto, argumento"},{"surface":"during","pos":"preposition","ipa":"/ˈdʊrɪŋ/","gloss":"durante"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"meeting","pos":"noun","ipa":"/ˈmiːtɪŋ/","gloss":"reunião"}]'::jsonb, NULL, NULL),
  ('unit-collocations-b2-08-03', 'lesson-collocations-b2-08', 3, 'sentence', 'I will give you some feedback tomorrow.', 'Vou te dar um retorno amanhã.', '/aɪ wɪl ɡɪv juː sʌm ˈfiːdbæk təˈmɑːroʊ/', '"Give feedback" = dar retorno; "feedback" não tem plural.', '[]'::jsonb, '[{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"will","pos":"modal verb","ipa":"/wɪl/","gloss":"marca de futuro"},{"surface":"give","pos":"verb","ipa":"/ɡɪv/","gloss":"dar"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"some","pos":"determiner","ipa":"/sʌm/","gloss":"algumas"},{"surface":"feedback","pos":"noun","ipa":"/ˈfiːdbæk/","gloss":"retorno, feedback"},{"surface":"tomorrow","pos":"adverb","ipa":"/təˈmɑːroʊ/","gloss":"amanhã"}]'::jsonb, NULL, NULL),
  ('unit-collocations-b2-08-04', 'lesson-collocations-b2-08', 4, 'sentence', 'He broke the news to his family.', 'Ele deu a notícia para a família.', '/hiː broʊk ðə nuːz tuː hɪz ˈfæməli/', '"Break the news" = contar uma notícia importante.', '[]'::jsonb, '[{"surface":"He","pos":"pronoun","ipa":"/hiː/","gloss":"ele"},{"surface":"broke","pos":"verb","ipa":"/broʊk/","gloss":"quebrou"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"news","pos":"noun","ipa":"/nuːz/","gloss":"notícia(s)"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"his","pos":"determiner","ipa":"/hɪz/","gloss":"dele"},{"surface":"family","pos":"noun","ipa":"/ˈfæməli/","gloss":"família"}]'::jsonb, NULL, NULL),
  ('unit-collocations-b2-08-05', 'lesson-collocations-b2-08', 5, 'sentence', 'Let me get back to you on that.', 'Deixa eu te dar uma resposta sobre isso depois.', '/lɛt miː ɡɛt bæk tuː juː ɑːn ðæt/', '"Get back to" = retornar depois.', '[]'::jsonb, '[{"surface":"Let","pos":"verb","ipa":"/lɛt/","gloss":"deixar, permitir"},{"surface":"me","pos":"pronoun","ipa":"/miː/","gloss":"me, mim"},{"surface":"get","pos":"verb","ipa":"/ɡɛt/","gloss":"conseguir, chegar"},{"surface":"back","pos":"adverb","ipa":"/bæk/","gloss":"de volta"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"you","pos":"pronoun","ipa":"/juː/","gloss":"você"},{"surface":"on","pos":"preposition","ipa":"/ɑːn/","gloss":"em, sobre"},{"surface":"that","pos":"pronoun","ipa":"/ðæt/","gloss":"isso, aquilo"}]'::jsonb, NULL, NULL),
  ('unit-collocations-b2-08-06', 'lesson-collocations-b2-08', 6, 'sentence', 'They exchanged phone numbers.', 'Eles trocaram números de telefone.', '/ðeɪ ɪksˈtʃeɪndʒd foʊn ˈnʌmbərz/', '"Exchange" = trocar entre as duas partes.', '[]'::jsonb, '[{"surface":"They","pos":"pronoun","ipa":"/ðeɪ/","gloss":"eles, elas"},{"surface":"exchanged","pos":"verb","ipa":"/ɪksˈtʃeɪndʒd/","gloss":"trocaram"},{"surface":"phone","pos":"noun","ipa":"/foʊn/","gloss":"celular, telefone"},{"surface":"numbers","pos":"noun","ipa":"/ˈnʌmbərz/","gloss":"números"}]'::jsonb, NULL, NULL),
  ('unit-collocations-b2-08-07', 'lesson-collocations-b2-08', 7, 'sentence', 'I would like to make a suggestion.', 'Eu gostaria de fazer uma sugestão.', '/aɪ wʊd laɪk tuː meɪk ə səɡˈdʒɛstʃən/', '"Make a suggestion" = sugerir.', '[]'::jsonb, '[{"surface":"I","pos":"pronoun","ipa":"/aɪ/","gloss":"eu"},{"surface":"would","pos":"modal verb","ipa":"/wʊd/","gloss":"gostaria; condicional"},{"surface":"like","pos":"verb","ipa":"/laɪk/","gloss":"gostar"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"make","pos":"verb","ipa":"/meɪk/","gloss":"fazer; conseguir ir (make it)"},{"surface":"a","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"suggestion","pos":"noun","ipa":"/səɡˈdʒɛstʃən/","gloss":"sugestão"}]'::jsonb, NULL, NULL),
  ('unit-collocations-b2-08-08', 'lesson-collocations-b2-08', 8, 'sentence', 'Please keep your voice down.', 'Fale mais baixo, por favor.', '/pliːz kiːp jʊr vɔɪs daʊn/', '"Keep your voice down" = falar baixo.', '[]'::jsonb, '[{"surface":"Please","pos":"adverb","ipa":"/pliːz/","gloss":"por favor"},{"surface":"keep","pos":"verb","ipa":"/kiːp/","gloss":"manter"},{"surface":"your","pos":"determiner","ipa":"/jʊr/","gloss":"seu, sua"},{"surface":"voice","pos":"noun","ipa":"/vɔɪs/","gloss":"voz"},{"surface":"down","pos":"adjective","ipa":"/daʊn/","gloss":"dentro, topando (gíria)"}]'::jsonb, NULL, NULL),
  ('unit-collocations-b2-08-09', 'lesson-collocations-b2-08', 9, 'sentence', 'She expressed her concern about the delay.', 'Ela expressou preocupação com o atraso.', '/ʃiː ɪkˈsprɛst hɜːr kənˈsɜːrn əˈbaʊt ðə dɪˈleɪ/', '"Express concern" = demonstrar preocupação.', '[]'::jsonb, '[{"surface":"She","pos":"pronoun","ipa":"/ʃiː/","gloss":"ela"},{"surface":"expressed","pos":"verb","ipa":"/ɪkˈsprɛst/","gloss":"expressou"},{"surface":"her","pos":"determiner","ipa":"/hɜːr/","gloss":"dela; a, lhe"},{"surface":"concern","pos":"noun","ipa":"/kənˈsɜːrn/","gloss":"preocupação"},{"surface":"about","pos":"preposition","ipa":"/əˈbaʊt/","gloss":"sobre"},{"surface":"the","pos":"determiner","ipa":"/ðə/","gloss":"o, a"},{"surface":"delay","pos":"noun","ipa":"/dɪˈleɪ/","gloss":"atraso"}]'::jsonb, NULL, NULL),
  ('unit-collocations-b2-08-10', 'lesson-collocations-b2-08', 10, 'sentence', 'We reached a point where we had to talk.', 'Chegamos a um ponto em que precisávamos conversar.', '/wiː riːtʃt ə pɔɪnt wɛr wiː hæd tuː tɔːk/', '"Reach a point" = chegar a um ponto.', '[]'::jsonb, '[{"surface":"We","pos":"pronoun","ipa":"/wiː/","gloss":"nós, a gente"},{"surface":"reached","pos":"verb","ipa":"/riːtʃt/","gloss":"alcançou"},{"surface":"a","pos":"determiner","ipa":"/ə/","gloss":"um, uma"},{"surface":"point","pos":"noun","ipa":"/pɔɪnt/","gloss":"ponto, argumento"},{"surface":"where","pos":"adverb","ipa":"/wɛr/","gloss":"onde"},{"surface":"we","pos":"pronoun","ipa":"/wiː/","gloss":"nós, a gente"},{"surface":"had","pos":"verb","ipa":"/hæd/","gloss":"teve, tinha"},{"surface":"to","pos":"preposition","ipa":"/tuː/","gloss":"para, a"},{"surface":"talk","pos":"verb","ipa":"/tɔːk/","gloss":"falar"}]'::jsonb, NULL, NULL)
